p='src/cart.js'
s=open(p).read()
s=s.replace("""// Retruns the sum of price * qty for every item.
function cartTotal(items) {
  let total = 0;
  for (let i = 1; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return total;
}
""","""// Applies a discount to an amount in cents, never going below zero.
// discount is { type: 'percent', value } (0-100) or { type: 'fixed', value } (cents).
function applyDiscount(amount, discount) {
  if (!discount) return amount;
  let off;
  if (discount.type === 'percent') {
    if (!(discount.value >= 0 && discount.value <= 100)) {
      throw new RangeError('percent discount must be between 0 and 100');
    }
    off = Math.round(amount * discount.value / 100);
  } else if (discount.type === 'fixed') {
    if (!(discount.value >= 0)) {
      throw new RangeError('fixed discount must not be negative');
    }
    off = discount.value;
  } else {
    throw new TypeError('unknown discount type: ' + (discount && discount.type));
  }
  return Math.max(0, amount - off);
}

// Returns the sum of price * qty for every item, minus an optional discount.
function cartTotal(items, discount) {
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return applyDiscount(total, discount);
}
""")
s=s.replace("""function cartLabel(items) {
  return 'Total: ' + formatPrice(cartTotal(items));""","""function cartLabel(items, discount) {
  return 'Total: ' + formatPrice(cartTotal(items, discount));""")
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, applyDiscount }")
open(p,'w').write(s)
p='test/cart.test.js'
s=open(p).read()
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, applyDiscount }")
s+="""
test('percent discount reduces the total', () => {
  const items = [{ price: 250, qty: 2 }, { price: 100, qty: 1 }];
  assert.strictEqual(cartTotal(items, { type: 'percent', value: 10 }), 540);
});

test('fixed discount reduces the total and floors at zero', () => {
  const items = [{ price: 500, qty: 1 }];
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 200 }), 300);
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 900 }), 0);
});

test('cartLabel applies the discount', () => {
  assert.strictEqual(cartLabel([{ price: 2000, qty: 1 }], { type: 'percent', value: 50 }), 'Total: $10.00');
});

test('applyDiscount rejects invalid discounts', () => {
  assert.throws(() => applyDiscount(100, { type: 'percent', value: 150 }), RangeError);
  assert.throws(() => applyDiscount(100, { type: 'fixed', value: -5 }), RangeError);
  assert.throws(() => applyDiscount(100, { type: 'bogus', value: 5 }), TypeError);
});
"""
open(p,'w').write(s)
